// login.component.ts
export class LoginComponent {
  username = '';
  password = '';

  onSubmit(form: any) {
    console.log('Submitted:', form.value);
    form.reset();
  }
}

// login.component.html
<form #loginForm="ngForm" (ngSubmit)="onSubmit(loginForm)">
  <div>
    <label>Username</label>
    <input name="username" [(ngModel)]="username" required minlength="4" #usernameRef="ngModel">
    <div *ngIf="usernameRef.invalid && usernameRef.touched">
      <small *ngIf="usernameRef.errors?.required">Username is required.</small>
      <small *ngIf="usernameRef.errors?.minlength">Minimum 4 characters.</small>
    </div>
  </div>
  <div>
    <label>Password</label>
    <input name="password" type="password" [(ngModel)]="password" required #passwordRef="ngModel">
    <div *ngIf="passwordRef.invalid && passwordRef.touched">
      <small>Password is required.</small>
    </div>
  </div>
  <button type="submit" [disabled]="!loginForm.valid">Login</button>
</form>
